package com.foodydelivery.tracker.order; import jakarta.validation.constraints.*; public final class OrderDtos {private OrderDtos(){} public record CreateRequest(@NotBlank String customer,@NotBlank String items,@NotBlank String deliveryAddress,@Size(max=200) String complement){} public record StatusRequest(@NotNull OrderStatus status){} public record Response(Long id,String customer,String items,String deliveryAddress,String complement,OrderStatus status,java.time.Instant createdAt){static Response of(Order o){return new Response(o.getId(),o.getCustomer(),o.getItems(),o.getDeliveryAddress(),o.getComplement(),o.getStatus(),o.getCreatedAt());}}}
